import {readDOCX} from './docx-import.mjs';
import {googleReady, prepareGoogle, chooseGoogleDocuments, disconnectGoogle, validateGoogleConfig} from './google-import.mjs';
import {documentDrafts, duplicateEntries, sourceURL, importRecord} from './import-tools.mjs';
import {icon, brandDefs, brandMark, contours} from './icons.mjs';
const VERSION='0.5';
// Region names are part of the backup format: keep them stable. Icon key and accent hue are presentation only.
const regionMeta={'Hip':['hip','#527DFF'],'Knee':['knee','#18A999'],'Shoulder':['shoulder','#7C5CFF'],'Spine':['spine','#0EA5E9'],'Ankle & Foot':['foot','#F59E0B'],'Neurological':['neuro','#D946EF'],'Cardiopulmonary':['cardio','#F43F5E'],'Balance & Vestibular':['vestibular','#06B6D4'],'Elbow / Wrist / Hand':['hand','#F97316'],'Other':['other','#64748B']};
const regions=Object.keys(regionMeta);
const categories=['Therapeutic Exercise','Functional Training','Gait Training','Balance Training','Manual Therapy','Neuromuscular Re-education','Patient Education','Other'];
const statuses=[['draft','Draft'],['unreviewed','Needs review'],['reviewed','Reviewed']];
const examples=[['Hip','Total Hip Arthroplasty (THA)'],['Hip','Femoroacetabular Impingement (FAI)'],['Hip','Hip Osteoarthritis'],['Hip','Greater Trochanteric Pain Syndrome'],['Knee','Total Knee Arthroplasty (TKA)'],['Knee','ACL Reconstruction'],['Knee','Patellofemoral Pain'],['Shoulder','Rotator Cuff Pathology'],['Shoulder','Adhesive Capsulitis'],['Spine','Low Back Pain'],['Spine','Cervical Radiculopathy'],['Ankle & Foot','Lateral Ankle Sprain'],['Ankle & Foot','Achilles Tendinopathy'],['Neurological','Stroke Rehabilitation'],['Neurological','Parkinson Disease'],['Cardiopulmonary','COPD'],['Balance & Vestibular','BPPV']];
const conditionTabs=[['overview','Overview'],['precautions','Precautions'],['protocol','Protocols'],['interventions','Interventions'],['evidence','Evidence'],['notes','Notes']];
let pendingProvenance=null;
let importBatch=[],importMetadata={},textFileMetadata={};
let freshDatabase=false;
let db,items=[],conditions=[],view='home',activeRegion='',activeCondition='',query='',editId=null,notice='',offlineReady=false;
let theme=readSetting('atlas-theme','system'),sidebarCollapsed=readSetting('atlas-sidebar','')==='collapsed',conditionTab='overview',storageInfo={persisted:false,usage:0,quota:0};
let filters=emptyFilters();
function emptyFilters(){return {region:'',category:'',status:'',source:'',favorites:false}}
function readSetting(key,fallback){try{return localStorage.getItem(key)||fallback}catch{return fallback}}
function writeSetting(key,value){try{localStorage.setItem(key,value)}catch{}}
const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random();
const today=()=>new Date().toISOString().slice(0,10);
const hue=region=>(regionMeta[region]||regionMeta.Other)[1];
const regionIcon=(region,size)=>icon((regionMeta[region]||regionMeta.Other)[0],size);
const plural=(n,word)=>`${n} ${word}${n===1?'':'s'}`;
const statusOf=x=>x.reviewStatus||'draft';
const statusLabel=x=>(statuses.find(([k])=>k===statusOf(x))||statuses[0])[1];
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('pt-atlas-library',1);r.onupgradeneeded=()=>{freshDatabase=true;const d=r.result;d.createObjectStore('interventions',{keyPath:'id'});d.createObjectStore('conditions',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function all(store){return new Promise((res,rej)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function put(store,obj){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(obj);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
function remove(store,id){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).delete(id);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
async function reload(){items=await all('interventions');conditions=await all('conditions');render()}
function setView(v,r='',c=''){view=v;activeRegion=r;activeCondition=c;editId=null;query='';filters=emptyFilters();conditionTab='overview';render();window.scrollTo(0,0)}
function msg(message){
 notice=message;document.querySelector('.notice')?.remove();const node=document.createElement('div');node.className='notice';node.role='status';node.textContent=message;$('#content')?.before(node);
 setTimeout(()=>{if(notice===message){notice='';document.querySelector('.notice')?.remove();}},4000);
}
const btn=(label,action,extra='',glyph='')=>`<button type="button" class="btn ${extra}" data-action="${action}">${glyph?icon(glyph,18):''}${label}</button>`;
const kicker=(text,region)=>`<p class="kicker"${region?` style="--hue:${hue(region)}"`:''}><span class="kicker-mark" aria-hidden="true"></span>${text}</p>`;
function counts(region){return conditions.filter(c=>c.region===region).length}

// ——— Shell ———
const navItems=[['home','home','Home'],['library','library','Library'],['favorites','heart','Favorites'],['import','import','Import'],['settings','settings','Settings']];
function nav(){return navItems.map(([v,i,t])=>`<button class="${view===v?'active':''}" data-nav="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${t}</span></button>`).join('')}
function networkText(){return navigator.onLine?(offlineReady?'Online · offline ready':'Online · preparing offline cache'):(offlineReady?'Offline · working from cache':'Offline · cache unavailable')}
function storageText(){return storageInfo.persisted?'Saved on this device · protected':'Saved on this device'}
const themeIcon=()=>theme==='light'?'sun':theme==='dark'?'moon':'system';
function header(){return `<header class="topbar"><button type="button" class="iconbtn sidebar-toggle" data-action="toggle-sidebar" aria-label="${sidebarCollapsed?'Expand':'Collapse'} sidebar" aria-expanded="${!sidebarCollapsed}">${icon('sidebar')}</button><div class="mobile-brand">${brandMark(30)}<span>ATLAS</span></div><label class="search">${icon('search',18)}<input id="globalSearch" type="search" placeholder="Search your library…" value="${escapeHTML(query)}" aria-label="Search library" autocomplete="off"><kbd aria-hidden="true">/</kbd></label><div class="status-pills"><span class="pill ${navigator.onLine?'ok':'warn'}" id="netStatus" role="status">${icon('wifi',14)}<span>${networkText()}</span></span><span class="pill" id="storeStatus">${icon('database',14)}<span>${storageText()}</span></span></div><button type="button" class="iconbtn" data-action="cycle-theme" aria-label="Theme: ${theme}. Change theme">${icon(themeIcon())}</button><button type="button" class="btn primary small new-btn" data-action="add" aria-label="New intervention">${icon('plus',16)}<span>New</span></button></header>`}
function sidebar(){return `<aside class="side" aria-label="Primary"><div class="brand">${brandMark(38)}<div class="wordmark"><strong>PT Atlas</strong><small>Clinical knowledge, anywhere.</small></div></div><nav class="nav" aria-label="Sections">${nav()}</nav><div class="side-card"><p>${icon('shield',16)}<span>Personal reference library. Clinician judgment and patient-specific orders govern care.</span></p></div></aside>`}
function tabbar(){return `<nav class="tabbar" aria-label="Sections">${[['home','home','Home'],['library','library','Library'],['editor','plus','Add'],['favorites','heart','Saved'],['settings','settings','Settings']].map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''} ${v==='editor'?'tab-add':''}" ${view===v?'aria-current="page"':''}>${icon(i,22)}<span>${t}</span></button>`).join('')}</nav>`}

// ——— Cards ———
function regionTiles(){return `<div class="tiles">${regions.map(r=>{const n=items.filter(x=>x.region===r).length;return `<button class="tile" data-region="${escapeHTML(r)}" style="--hue:${hue(r)}"><span class="tile-icon">${regionIcon(r,26)}</span><span class="tile-body"><h3>${escapeHTML(r)}</h3><span class="tile-meta">${plural(counts(r),'condition')} · ${plural(n,'intervention')}</span></span><span class="tile-arrow">${icon('arrow',18)}</span></button>`}).join('')}</div>`}
function badges(x){let out='';if(x.importedAt)out+=`<span class="badge imported">Imported</span>`;if(statusOf(x)==='unreviewed')out+=`<span class="badge warn">Needs review</span>`;else if(statusOf(x)==='reviewed')out+=`<span class="badge ok">${icon('shield',12)}Reviewed</span>`;return out}
function itemCard(x){return `<article class="row" style="--hue:${hue(x.region)}"><span class="row-icon">${regionIcon(x.region,22)}</span><div class="row-body">${kicker(escapeHTML(x.region||'Uncategorized')+(x.condition?' · '+escapeHTML(x.condition):''),x.region)}<h3>${escapeHTML(x.name)}</h3><div class="chips">${x.category?`<span class="chip">${escapeHTML(x.category)}</span>`:''}${x.tags?x.tags.split(',').map(t=>t.trim()).filter(Boolean).slice(0,4).map(t=>`<span class="chip">#${escapeHTML(t)}</span>`).join(''):''}${badges(x)}</div></div><div class="row-actions"><button class="iconbtn fav ${x.favorite?'on':''}" data-fav="${escapeHTML(x.id)}" aria-pressed="${!!x.favorite}" aria-label="${x.favorite?'Remove from':'Add to'} favorites: ${escapeHTML(x.name)}">${icon(x.favorite?'heartFill':'heart')}</button><button class="btn ghost small" data-open="${escapeHTML(x.id)}">View${icon('chevron',16)}</button></div></article>`}
function conditionCard(c){const n=items.filter(x=>x.condition===c.name&&x.region===c.region).length;return `<button class="row row-link" data-condition="${escapeHTML(c.name)}" data-c-region="${escapeHTML(c.region)}" style="--hue:${hue(c.region)}"><span class="row-icon">${regionIcon(c.region,22)}</span><span class="row-body">${kicker(escapeHTML(c.region),c.region)}<h3>${escapeHTML(c.name)}</h3><span class="row-meta">${plural(n,'linked intervention')}${c.protocol?' · Protocol':''}${c.precautions?' · Precautions':''}</span></span><span class="row-chevron">${icon('chevron')}</span></button>`}
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-mark">${brandMark(44,{tile:false})}</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
function sectionHead(title,aside=''){return `<div class="sectionhead"><h2>${title}</h2>${aside}</div>`}

// ——— Filters ———
function applyFilters(list){return list.filter(x=>(!filters.region||x.region===filters.region)&&(!filters.category||x.category===filters.category)&&(!filters.status||statusOf(x)===filters.status)&&(!filters.source||(filters.source==='imported')===!!x.importedAt)&&(!filters.favorites||x.favorite))}
function filterBar(showRegion=true){const select=(key,label,options)=>`<label class="filter"><span>${label}</span><select data-filter="${key}"><option value="">All</option>${options.map(([v,t])=>`<option value="${escapeHTML(v)}" ${filters[key]===v?'selected':''}>${escapeHTML(t)}</option>`).join('')}</select></label>`;return `<div class="filters" role="group" aria-label="Filter interventions">${showRegion?select('region','Region',regions.map(r=>[r,r])):''}${select('category','Type',categories.map(c=>[c,c]))}${select('status','Review',statuses)}${select('source','Source',[['imported','Imported'],['authored','Authored here']])}<label class="toggle"><input type="checkbox" data-filter="favorites" ${filters.favorites?'checked':''}><span>Favorites only</span></label></div>`}

// ——— Views ———
function home(){const recent=[...items].sort((a,b)=>(b.updated||'').localeCompare(a.updated||'')).slice(0,5);const unreviewed=items.filter(x=>statusOf(x)==='unreviewed').length;return `<section class="hero"><div class="hero-copy">${kicker('PT Atlas · Your clinical library')}<h1 class="display">Clinical knowledge,<br><span class="grad">anywhere.</span></h1><p class="lede">Every intervention, protocol and precaution you rely on, organized by body region and condition. It stays with you, even offline.</p><div class="actions">${btn('Add intervention','add','primary','plus')}<button type="button" class="link-cta" data-action="library">Explore the library${icon('chevron',16)}</button></div></div><div class="hero-art" aria-hidden="true"><svg class="contours" viewBox="0 0 600 500" preserveAspectRatio="xMidYMid slice">${contours}</svg><div class="hero-mark">${brandMark(168,{tile:false})}</div></div></section><section class="stats" aria-label="Library summary"><div class="stat" style="--hue:#527DFF"><b>${items.length}</b><span>Interventions</span></div><div class="stat" style="--hue:#18A999"><b>${conditions.length}</b><span>Conditions</span></div><div class="stat" style="--hue:#F43F5E"><b>${items.filter(x=>x.favorite).length}</b><span>Favorites</span></div><div class="stat" style="--hue:#F59E0B"><b>${unreviewed}</b><span>Need review</span></div></section>${sectionHead('Browse by region.',`<button type="button" class="link-cta" data-action="library">See all${icon('chevron',16)}</button>`)}${regionTiles()}<div class="split"><section>${sectionHead('Latest.')}${recent.length?`<ol class="stream">${recent.map((x,i)=>`<li style="--hue:${hue(x.region)}"><span class="num">${String(i+1).padStart(2,'0')}</span><div>${kicker(escapeHTML(x.region)+(x.condition?' · '+escapeHTML(x.condition):''),x.region)}<button type="button" class="stream-title" data-open="${escapeHTML(x.id)}">${escapeHTML(x.name)}</button><p class="row-meta">Updated ${escapeHTML(x.updated||'—')}${x.category?' · '+escapeHTML(x.category):''}</p></div></li>`).join('')}</ol>`:empty('Your library is ready.','Add your first intervention or bring in existing notes from a document.',`<div class="actions center">${btn('Create your first entry','add','primary')}${btn('Import notes','import','ghost')}</div>`)}</section><aside class="callout">${icon('shield',22)}<h3>Built for your judgment, not instead of it.</h3><p>PT Atlas never generates dosages, restrictions or progression criteria. Everything here is what you write or import and review. Surgical protocols depend on the treating surgeon or provider.</p><p class="row-meta">No accounts. No trackers. Your library lives in this browser. Export backups regularly and never store patient-identifying information.</p></aside></div>`}
function library(){if(activeRegion)filters.region=activeRegion;const matches=conditions.filter(c=>!activeRegion||c.region===activeRegion).sort((a,b)=>a.name.localeCompare(b.name));const entries=applyFilters(items).sort((a,b)=>a.name.localeCompare(b.name));const head=activeRegion?`<div class="page-head region-head" style="--hue:${hue(activeRegion)}"><nav class="breadcrumb" aria-label="Breadcrumb"><button data-nav="library">Library</button>${icon('chevron',14)}<span>${escapeHTML(activeRegion)}</span></nav><div class="region-title"><span class="tile-icon big">${regionIcon(activeRegion,34)}</span><div>${kicker('Body region',activeRegion)}<h1>${escapeHTML(activeRegion)}</h1></div></div>`:`<div class="page-head">${kicker('Explore')}<h1>Your library</h1><p class="lede small">Browse by body region, open a condition, or filter every intervention you’ve saved.</p>`;return `${head}<div class="actions">${btn('Add intervention','add','primary','plus')}${btn('Add condition','add-condition','ghost','plus')}${activeRegion?btn('All regions','all-regions','ghost','back'):''}</div></div>${!activeRegion?`${sectionHead('Body regions.')}${regionTiles()}`:''}${sectionHead('Conditions.',`<span class="count">${matches.length}</span>`)}<div class="list">${matches.length?matches.map(conditionCard).join(''):empty('No conditions here yet.','Add a condition to start organizing this region.')}</div>${sectionHead('Interventions.',`<span class="count">${entries.length}</span>`)}${filterBar(!activeRegion)}<div class="list">${entries.length?entries.map(itemCard).join(''):empty('No interventions match.','Add an intervention or adjust the filters.')}</div>`}
function tabContent(c,entries){
 const text=(value,placeholder)=>value?`<div class="prose">${escapeHTML(value)}</div>`:`<p class="placeholder">${placeholder}</p>`;
 switch(conditionTab){
  case 'precautions':return `<div class="warning">${icon('alert',18)}<span>Always verify patient-specific orders, procedure details and the current source protocol. Notes in this personal library are not independently clinically verified.</span></div>${text(c.precautions,'No precautions or contraindications entered yet. Use Edit condition to add them from your source.')}`;
  case 'protocol':return `<div class="warning info">${icon('doc',18)}<span>Rehabilitation phases, restrictions and progression criteria for surgical conditions depend on the treating surgeon’s or provider’s protocol. Record the source and date with each phase.</span></div>${text(c.protocol,'No protocol entered yet. Add phases with objectives, restrictions, criteria to progress and source.')}`;
  case 'interventions':return `<div class="list">${entries.length?entries.map(itemCard).join(''):empty('No interventions linked yet.','Add an intervention and set this condition to link it.')}</div>`;
  case 'evidence':return text(c.source,'No evidence or references recorded yet. Add citations or source links with Edit condition.');
  case 'notes':return text(c.notes,'No personal notes yet.');
  default:return `${text(c.overview,'Add a clinical overview for this condition.')}<dl class="facts"><div><dt>Linked interventions</dt><dd>${entries.length}</dd></div><div><dt>Precautions</dt><dd>${c.precautions?'Documented':'Not yet'}</dd></div><div><dt>Protocol</dt><dd>${c.protocol?'Documented':'Not yet'}</dd></div><div><dt>Last updated</dt><dd>${escapeHTML(c.updated||'—')}</dd></div></dl>`;
 }
}
function conditionPage(){const c=conditions.find(x=>x.name===activeCondition&&x.region===activeRegion);if(!c)return library();const entries=items.filter(x=>x.condition===c.name&&x.region===c.region);const tab=conditionTabs.find(([k])=>k===conditionTab)||conditionTabs[0];return `<div class="page-head region-head" style="--hue:${hue(c.region)}"><nav class="breadcrumb" aria-label="Breadcrumb"><button data-nav="library">Library</button>${icon('chevron',14)}<button data-region="${escapeHTML(c.region)}">${escapeHTML(c.region)}</button>${icon('chevron',14)}<span>${escapeHTML(c.name)}</span></nav>${kicker('Clinical reference',c.region)}<h1>${escapeHTML(c.name)}</h1><div class="actions">${btn('Add intervention','add','primary','plus')}${btn('Edit condition','edit-condition','ghost','edit')}</div></div><div class="segmented" role="tablist" aria-label="Condition sections">${conditionTabs.map(([k,label])=>`<button type="button" role="tab" id="tab-${k}" data-tab="${k}" aria-selected="${k===tab[0]}" aria-controls="tabpanel" tabindex="${k===tab[0]?0:-1}">${label}${k==='interventions'?` <span class="tab-count">${entries.length}</span>`:''}</button>`).join('')}</div><section class="panel tabpanel" role="tabpanel" id="tabpanel" aria-labelledby="tab-${tab[0]}" tabindex="0"><h2 class="sr-only">${tab[1]}</h2>${tabContent(c,entries)}</section>`}
function detail(){const x=items.find(i=>i.id===editId);if(!x)return library();const sections=[['Clinical purpose',x.purpose],['Setup & positioning',x.setup],['Instructions',x.instructions],['Dosage',x.dosage],['Equipment',x.equipment],['Progressions & regressions',x.progressions],['Precautions & contraindications',x.precautions],['Evidence & references',x.source],['Personal notes',x.notes]];const history=readImportHistory(x.importHistory);return `<div class="page-head region-head" style="--hue:${hue(x.region)}"><nav class="breadcrumb" aria-label="Breadcrumb"><button data-nav="library">Library</button>${icon('chevron',14)}<button data-region="${escapeHTML(x.region)}">${escapeHTML(x.region)}</button>${icon('chevron',14)}<span>${escapeHTML(x.name)}</span></nav>${kicker('Intervention · '+escapeHTML(x.category||'Uncategorized'),x.region)}<h1>${escapeHTML(x.name)}</h1><div class="chips">${badges(x)}</div><div class="actions">${btn('Edit intervention','edit','primary','edit')}<button type="button" class="btn ghost ${x.favorite?'fav-on':''}" data-action="favorite-detail" aria-pressed="${!!x.favorite}">${icon(x.favorite?'heartFill':'heart',18)}${x.favorite?'Favorited':'Favorite'}</button>${btn('Delete','delete','danger','trash')}</div></div><div class="detail"><div class="detail-main">${sections.filter(([,v])=>v).map(([h,v],i)=>`<section class="panel numbered"><span class="num">${String(i+1).padStart(2,'0')}</span><div><h2>${h}</h2><div class="prose">${escapeHTML(v)}</div></div></section>`).join('')}${sections.some(([,v])=>!v)?`<section class="panel undocumented"><h2>Not yet documented</h2><ul>${sections.filter(([,v])=>!v).map(([h])=>`<li>${h}</li>`).join('')}</ul><button type="button" class="link-cta" data-action="edit">Add details${icon('chevron',16)}</button></section>`:''}</div><aside class="detail-side"><div class="panel glance"><h2>At a glance</h2><dl><div><dt>Region</dt><dd>${escapeHTML(x.region)}</dd></div><div><dt>Condition</dt><dd>${x.condition?`<button type="button" class="linkish" data-condition="${escapeHTML(x.condition)}" data-c-region="${escapeHTML(x.region)}">${escapeHTML(x.condition)}</button>`:'General'}</dd></div><div><dt>Type</dt><dd>${escapeHTML(x.category||'—')}</dd></div><div><dt>Review status</dt><dd>${statusLabel(x)}${x.reviewedAt?' · '+escapeHTML(x.reviewedAt):''}</dd></div><div><dt>Author</dt><dd>${escapeHTML(x.author||'—')}</dd></div><div><dt>Last updated</dt><dd>${escapeHTML(x.updated||'Unknown')}</dd></div>${x.tags?`<div><dt>Tags</dt><dd>${escapeHTML(x.tags)}</dd></div>`:''}</dl></div>${x.importedAt||x.importHistory?`<div class="panel glance provenance"><h2>Import provenance</h2><p>Review status: ${escapeHTML(x.reviewStatus||'unreviewed')} · Imported ${escapeHTML(x.importedAt)}<br>Document: ${escapeHTML(x.sourceTitle)}<br>File: ${escapeHTML(x.sourceFile||'Pasted text')}<br>Source modified: ${escapeHTML(x.sourceModifiedAt||'Not supplied')}</p>${history.map(entry=>`<p>Merged document: ${escapeHTML(entry.documentTitle)} · ${escapeHTML(entry.source||entry.fileName||'Pasted text')} · Imported ${escapeHTML(entry.importedAt)} · Source modified ${escapeHTML(entry.fileModifiedAt||'Not supplied')}</p>`).join('')}</div>`:''}<p class="fineprint">Source information is user-provided and unverified.</p></aside></div>`}
function field(name,label,value,{type='textarea',hint='',required=false,placeholder=''}={}){const control=type==='textarea'?`<textarea name="${name}" placeholder="${escapeHTML(placeholder)}">${escapeHTML(value)}</textarea>`:`<input name="${name}" type="${type}" value="${escapeHTML(value)}" placeholder="${escapeHTML(placeholder)}" ${required?'required':''} maxlength="400">`;return `<div class="field"><label>${label}</label>${control}${hint?`<small>${hint}</small>`:''}</div>`}
function editor(){const x=items.find(i=>i.id===editId)||{};const status=x.reviewStatus||(pendingProvenance?'unreviewed':'draft');return `<div class="page-head">${kicker('Your library')}<h1>${x.id?'Edit':'New'} intervention</h1><p class="lede small">Build a reusable, searchable entry. Every field is yours to write and can be updated anytime.</p></div><form class="form" id="interventionForm"><fieldset class="panel"><legend>Basics</legend><div class="field"><label for="name">Intervention name *</label><input id="name" name="name" required maxlength="160" value="${escapeHTML(x.name)}" placeholder="e.g. Sit-to-stand training"></div><div class="two"><div class="field"><label for="region">Body region *</label><select id="region" name="region" required>${regions.map(r=>`<option ${r===(x.region||activeRegion)?'selected':''}>${escapeHTML(r)}</option>`).join('')}</select></div><div class="field"><label for="condition">Condition</label><input id="condition" name="condition" list="conditionOptions" value="${escapeHTML(x.condition||activeCondition)}" placeholder="Optional diagnosis"><datalist id="conditionOptions">${conditions.map(c=>`<option value="${escapeHTML(c.name)}">`).join('')}</datalist></div></div><div class="two"><div class="field"><label>Intervention type</label><select name="category">${categories.map(s=>`<option ${x.category===s?'selected':''}>${s}</option>`).join('')}</select></div>${field('tags','Tags (comma-separated)',x.tags,{type:'text',placeholder:'strength, early rehab'})}</div></fieldset><fieldset class="panel"><legend>Clinical content</legend>${[['purpose','Clinical purpose / target impairment'],['setup','Setup & positioning'],['instructions','Instructions / technique'],['dosage','Dosage / frequency','Enter dosage from your own source. PT Atlas never suggests defaults.'],['equipment','Equipment'],['progressions','Progressions & regressions'],['precautions','Precautions & contraindications']].map(([k,label,hint])=>field(k,label,x[k],{hint,placeholder:'Add '+label.toLowerCase()+'…'})).join('')}</fieldset><fieldset class="panel"><legend>Evidence & review</legend>${field('source','Evidence / source links',x.source,{placeholder:'Citations, guideline names, URLs…'})}<div class="two">${field('author','Author',x.author,{type:'text',placeholder:'Who wrote or verified this entry'})}<div class="field"><label>Review status</label><select name="reviewStatus">${statuses.map(([k,t])=>`<option value="${k}" ${k===status?'selected':''}>${t}</option>`).join('')}</select></div></div>${field('reviewedAt','Last reviewed',x.reviewedAt,{type:'date'})}</fieldset><fieldset class="panel"><legend>Notes</legend>${field('notes','Personal clinical notes',x.notes,{placeholder:'Anything you want to remember…'})}</fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save intervention</button>${btn('Cancel','cancel','ghost')}</div></form>`}
function conditionEditor(){const c=conditions.find(x=>x.name===activeCondition&&x.region===activeRegion)||{};return `<div class="page-head">${kicker('Clinical organization')}<h1>${c.id?'Edit':'New'} condition</h1><p class="lede small">Conditions are organizational labels. Write content from your own verified sources.</p></div><form class="form" id="conditionForm"><fieldset class="panel"><legend>Basics</legend><div class="field"><label>Condition name *</label><input name="name" required maxlength="160" value="${escapeHTML(c.name)}" placeholder="e.g. Total Hip Arthroplasty"></div><div class="field"><label>Body region</label><select name="region">${regions.map(r=>`<option ${r===(c.region||activeRegion)?'selected':''}>${escapeHTML(r)}</option>`).join('')}</select></div></fieldset><fieldset class="panel"><legend>Reference content</legend>${[['overview','Clinical overview'],['precautions','Precautions / contraindications'],['protocol','Protocols / rehabilitation phases','For each phase: objectives, restrictions, criteria to progress, source and date. Surgical protocols follow the treating provider.'],['source','Evidence / references'],['notes','Personal notes']].map(([k,l,hint])=>field(k,l,c[k],{hint})).join('')}</fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save condition</button>${btn('Cancel','cancel','ghost')}${c.id?btn('Delete condition','delete-condition','danger','trash'):''}</div></form>`}
function importer(){return `<div class="page-head">${kicker('Bring your knowledge')}<h1>Import your notes.</h1><p class="lede small">Paste text or load a document. Everything opens in a review step first, and nothing is saved until you confirm. No clinical facts are inferred.</p></div><div class="import-grid"><div class="panel"><h2>${icon('doc',20)} Documents & pasted text</h2><p class="muted">Open a Google Doc, copy its contents and paste below, or load a local .txt, .md or .docx file. The first nonempty line becomes the suggested title.</p><div class="form"><div class="field"><label for="textFile">Load a text, Markdown, or DOCX file</label><input type="file" id="textFile" accept=".txt,.md,.docx,text/plain,text/markdown,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></div><p id="fileStatus" class="muted" role="status" aria-live="polite"></p><div class="two"><div class="field"><label>Document title (optional)</label><input id="importTitle" placeholder="e.g. Hip intervention notes"></div><div class="field"><label>Source link (optional)</label><input id="importSource" placeholder="https://docs.google.com/document/d/..."></div></div><div class="field"><label>Paste document text *</label><textarea id="importText" class="tall" placeholder="Paste text from Google Docs here..."></textarea></div><label class="toggle"><input type="checkbox" id="splitSections"><span>Split Markdown level 1–2 headings into separate entries</span></label><div class="actions">${btn('Review as new intervention','review-import','primary')}${btn('Review batch import','review-batch','ghost')}</div></div></div>${googleImportPanel()}<div class="panel"><h2>${icon('download',20)} Restore PT Atlas JSON</h2><p class="muted">Import an exported backup. You’ll see how many records are added or replaced before anything changes. Entries with matching IDs are updated; others remain.</p><label class="filepick"><input type="file" id="restoreFile" accept=".json,application/json" aria-label="Select PT Atlas JSON backup"></label></div></div>`}
function fmtBytes(n){if(!n)return '0 MB';const mb=n/1048576;return mb<1?Math.max(1,Math.round(n/1024))+' KB':mb<1024?mb.toFixed(1)+' MB':(mb/1024).toFixed(1)+' GB'}
function settings(){const pct=storageInfo.quota?Math.min(100,storageInfo.usage/storageInfo.quota*100):0;return `<div class="page-head">${kicker('Preferences')}<h1>Settings</h1></div><div class="settings"><section class="panel"><h2>Appearance</h2><p class="muted">Match your device or choose a look for your clinical workspace.</p><div class="segmented compact" role="group" aria-label="Theme">${[['system','System','system'],['light','Light','sun'],['dark','Dark','moon']].map(([k,t,i])=>`<button type="button" data-action="theme-${k}" aria-pressed="${theme===k}">${icon(i,16)}${t}</button>`).join('')}</div></section><section class="panel"><h2>Your data</h2><p class="muted">Your library is stored locally in this browser using IndexedDB. No account or cloud sync is configured. Export backups regularly and do not store patient-identifying data.</p><div class="meter" role="img" aria-label="Storage used ${fmtBytes(storageInfo.usage)} of ${fmtBytes(storageInfo.quota)}"><span style="width:${pct.toFixed(1)}%"></span></div><p class="row-meta" id="storageDetail">${storageInfo.quota?`${fmtBytes(storageInfo.usage)} used of ${fmtBytes(storageInfo.quota)} available to this site.`:'Storage estimate unavailable in this browser.'} ${storageInfo.persisted?'Storage is marked persistent: the browser will not clear it automatically.':'Storage is best-effort: the browser may clear it under storage pressure.'}</p><div class="actions">${btn('Export JSON backup','export','primary','download')}${btn('Open importer','import','ghost','import')}${storageInfo.persisted?'':btn('Protect local data','persist','ghost','shield')}</div></section><section class="panel"><h2>Offline access</h2><p class="muted">${'serviceWorker' in navigator?(offlineReady?'The app shell is cached. PT Atlas opens and works without a connection on this device.':'The app shell is cached after the first successful visit over HTTPS or localhost.'):'This browser does not support service workers.'} Data remains in browser storage unless it is cleared.</p></section><section class="panel about"><div class="about-brand">${brandMark(56)}<div><h2>PT Atlas</h2><p class="row-meta">Version ${VERSION} · Local-first clinical library</p></div></div><p class="muted">This is not medical advice or a prescribing tool. Clinical content is user-entered and should be verified against authoritative sources and patient-specific instructions.</p></section></div>`}
function favorites(){const list=items.filter(x=>x.favorite);return `<div class="page-head">${kicker('Quick access')}<h1>Your favorites</h1><p class="lede small">The interventions you reach for most.</p></div><div class="list">${list.map(itemCard).join('')||empty('Nothing saved yet.','Tap the heart on any intervention to keep it here.')}</div>`}
function searchResults(){const q=query.trim().toLowerCase();const hit=x=>Object.values(x).some(v=>typeof v==='string'&&v.toLowerCase().includes(q));const found=applyFilters(items.filter(hit));const cs=conditions.filter(c=>(!filters.region||c.region===filters.region)&&hit(c));return `<div class="page-head">${kicker('Search')}<h1>Results for “${escapeHTML(query)}”</h1><p class="lede small">${found.length+cs.length} result${found.length+cs.length===1?'':'s'} across titles, conditions, regions, tags and notes.</p></div>${filterBar()}${sectionHead('Conditions.',`<span class="count">${cs.length}</span>`)}<div class="list">${cs.map(conditionCard).join('')||'<div class="empty slim">No matching conditions.</div>'}</div>${sectionHead('Interventions.',`<span class="count">${found.length}</span>`)}<div class="list">${found.map(itemCard).join('')||'<div class="empty slim">No matching interventions.</div>'}</div>`}
// Hash routes keep refresh, back/forward and shared links working on GitHub Pages without a server fallback.
function routeHash(){const e=encodeURIComponent;if(query.trim())return null;if(view==='home')return '#/';if(view==='library')return activeRegion?'#/region/'+e(activeRegion):'#/library';if(view==='condition')return '#/condition/'+e(activeRegion)+'/'+e(activeCondition);if(view==='detail')return '#/intervention/'+e(editId);if(['favorites','import','settings'].includes(view))return '#/'+view;return null}
function applyRoute(){const [name,...rest]=location.hash.replace(/^#\/?/,'').split('/').map(part=>{try{return decodeURIComponent(part)}catch{return ''}});view='home';activeRegion='';activeCondition='';editId=null;query='';filters=emptyFilters();conditionTab='overview';
 if(name==='library')view='library';else if(name==='region'&&regions.includes(rest[0])){view='library';activeRegion=rest[0]}else if(name==='condition'&&rest.length===2){view='condition';[activeRegion,activeCondition]=rest}else if(name==='intervention'&&rest[0]){view='detail';editId=rest[0]}else if(['favorites','import','settings'].includes(name))view=name}
function syncRoute(){const hash=routeHash();if(hash&&hash!==(location.hash||'#/'))history.pushState(null,'',hash)}
function applyTheme(){const dark=theme==='dark'||(theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#0B111C':'#F7F9FC')}
function render(){applyTheme();syncRoute();let content=query.trim()?searchResults():view==='home'?home():view==='library'?library():view==='condition'?conditionPage():view==='detail'?detail():view==='editor'?editor():view==='condition-editor'?conditionEditor():view==='favorites'?favorites():view==='import-review'?importReview():view==='import'?importer():settings();$('#app').innerHTML=`${brandDefs()}<a class="skip" href="#content">Skip to content</a><div class="shell ${sidebarCollapsed?'collapsed':''}">${sidebar()}<div class="stage">${header()}<main class="main" id="main">${notice?`<div class="notice" role="status">${escapeHTML(notice)}</div>`:''}<div id="content" tabindex="-1">${content}</div><footer class="footer"><span>${brandMark(20)} PT Atlas</span><p>A personal reference library, not a substitute for professional judgment or patient-specific orders. No patient-identifying information.</p></footer></main></div></div>${tabbar()}`;document.querySelectorAll('.field').forEach((field,index)=>{const label=field.querySelector('label'),input=field.querySelector('input,select,textarea');if(label&&input){input.id=input.id||'field-'+index;label.htmlFor=input.id}})}
async function saveIntervention(form){const data=Object.fromEntries(new FormData(form).entries());if(data.reviewStatus==='reviewed'&&!data.reviewedAt)data.reviewedAt=today();const old=items.find(x=>x.id===editId);const obj={...old,...(old?{}:pendingProvenance||{}),...data,id:old?.id||uid(),favorite:old?.favorite||false,updated:today()};await put('interventions',obj);pendingProvenance=null;editId=obj.id;view='detail';await reload();msg('Intervention saved locally')}
async function saveCondition(form){const data=Object.fromEntries(new FormData(form).entries());const old=conditions.find(x=>x.name===activeCondition&&x.region===activeRegion);const obj={...old,...data,id:old?.id||uid(),updated:today()};if(conditions.some(c=>c.id!==obj.id&&c.name===obj.name&&c.region===obj.region))throw Error('A condition with this name already exists in this region');
const tx=db.transaction(['conditions','interventions'],'readwrite');tx.objectStore('conditions').put(obj);if(old)for(const item of items.filter(i=>i.region===old.region&&i.condition===old.name))tx.objectStore('interventions').put({...item,region:obj.region,condition:obj.name});await transactionDone(tx);activeRegion=obj.region;activeCondition=obj.name;view='condition';await reload();msg('Condition saved locally')}
function download(text,name){const blob=new Blob([text],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function transactionDone(tx){return new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Storage transaction aborted'))})}
function validateBackup(obj){
 if(!obj||obj.format!=='pt-atlas'||obj.version!==1||!Array.isArray(obj.interventions)||!Array.isArray(obj.conditions))throw Error('Expected a PT Atlas version 1 backup');
 if(obj.interventions.length+obj.conditions.length>10000)throw Error('Too many records');
 const result={};for(const store of ['interventions','conditions']){const ids=new Set();result[store]=obj[store].map(entry=>{
 if(!entry||typeof entry!=='object'||Array.isArray(entry)||typeof entry.id!=='string'||!entry.id.trim()||typeof entry.name!=='string'||!entry.name.trim()||typeof entry.region!=='string'||!regions.includes(entry.region))throw Error('Invalid record in backup');
 if(ids.has(entry.id))throw Error('Duplicate record ID in backup');ids.add(entry.id);
 const clean={};for(const [k,v] of Object.entries(entry)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Invalid field');if(typeof v!=='string'&&typeof v!=='boolean')throw Error('Invalid field type');clean[k]=v}return clean})}return result;
}
async function restore(file){if(!file)return;try{if(file.size>5e6)throw Error('File is too large (5 MB limit)');const obj=validateBackup(JSON.parse(await file.text()));const replacements=obj.interventions.filter(x=>items.some(i=>i.id===x.id)).length+obj.conditions.filter(x=>conditions.some(c=>c.id===x.id)).length;
 if(!confirm(`Import ${obj.interventions.length} interventions and ${obj.conditions.length} conditions? ${replacements} existing records will be replaced; other records will remain.`))return;
 const tx=db.transaction(['interventions','conditions'],'readwrite');for(const store of ['interventions','conditions'])for(const entry of obj[store])tx.objectStore(store).put(entry);await transactionDone(tx);await reload();msg('Backup imported successfully')
 }catch(e){alert('Import failed: '+e.message)}}
async function refreshStorage(){try{const [estimate,persisted]=await Promise.all([navigator.storage?.estimate?.(),navigator.storage?.persisted?.()]);storageInfo={persisted:!!persisted,usage:estimate?.usage||0,quota:estimate?.quota||0}}catch{}const pill=$('#storeStatus span');if(pill)pill.textContent=storageText();if(view==='settings'&&!query.trim())render()}
function updateNetworkStatus(){const pill=$('#netStatus');if(!pill)return;pill.className='pill '+(navigator.onLine?'ok':'warn');pill.querySelector('span').textContent=networkText()}
function selectTab(key,focus){conditionTab=key;render();if(focus)$('#tab-'+key)?.focus()}

document.addEventListener('input',e=>{if(e.target.id==='globalSearch'){const pos=e.target.selectionStart;query=e.target.value;render();const input=$('#globalSearch');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{
 const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable;
 if((e.key==='/'&&!typing)||(e.key.toLowerCase()==='k'&&(e.metaKey||e.ctrlKey))){e.preventDefault();$('#globalSearch')?.focus();return}
 if(e.key==='Escape'&&e.target.id==='globalSearch'&&query){query='';render();$('#globalSearch').focus();return}
 if(e.target.getAttribute?.('role')==='tab'){const keys=conditionTabs.map(([k])=>k),i=keys.indexOf(conditionTab);const next={ArrowRight:(i+1)%keys.length,ArrowLeft:(i-1+keys.length)%keys.length,Home:0,End:keys.length-1}[e.key];if(next!==undefined){e.preventDefault();selectTab(keys[next],true)}}
});
document.addEventListener('change',async e=>{
 if(e.target.dataset.filter){const key=e.target.dataset.filter;filters[key]=key==='favorites'?e.target.checked:e.target.value;const focusKey=key;render();document.querySelector(`[data-filter="${focusKey}"]`)?.focus();return}
 if(e.target.id==='restoreFile')restore(e.target.files[0]);
 if(e.target.id==='textFile'){
  const file=e.target.files[0],input=e.target;if(!file)return;
  try{
   if(file.size>5e6)throw Error('File is too large (5 MB limit)');
   if(!/\.(txt|md|docx)$/i.test(file.name))throw Error('Choose a .txt, .md, or .docx file.');
   input.disabled=true;
   const text=/\.docx$/i.test(file.name)?await readDOCX(file):await file.text();
   if(!input.isConnected)return;
   textFileMetadata={fileName:file.name,fileModifiedAt:new Date(file.lastModified).toISOString(),sourceType:/\.docx$/i.test(file.name)?'docx':'text-file'};
   $('#importText').value=text;$('#importTitle').value=file.name.replace(/\.(txt|md|docx)$/i,'');$('#importSource').value='';
   $('#fileStatus').textContent=/\.docx$/i.test(file.name)?'DOCX text extracted locally. Review headings, lists, and tables. Images, comments, footnotes, exact numbering, and formatting are not imported.':'Text loaded. Review before saving.';
  }catch(error){if(input.isConnected){textFileMetadata={};$('#importText').value='';$('#importTitle').value='';$('#fileStatus').textContent='Import failed: '+error.message;}}
  finally{if(input.isConnected)input.disabled=false;}
 }
});
document.addEventListener('submit',async e=>{try{if(e.target.id==='interventionForm'){e.preventDefault();await saveIntervention(e.target)}if(e.target.id==='conditionForm'){e.preventDefault();await saveCondition(e.target)}}catch(err){alert('Save failed: '+err.message)}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-nav],[data-action],[data-region],[data-condition],[data-open],[data-fav],[data-tab]');if(!el)return;if(el.dataset.tab){selectTab(el.dataset.tab);return}if(el.dataset.nav){if(el.dataset.nav==='editor'){pendingProvenance=null;editId=null;view='editor';render();window.scrollTo(0,0)}else setView(el.dataset.nav);return}if(el.dataset.region){setView('library',el.dataset.region);return}if(el.dataset.condition){setView('condition',el.dataset.cRegion,el.dataset.condition);return}if(el.dataset.open){editId=el.dataset.open;view='detail';query='';render();window.scrollTo(0,0);return}if(el.dataset.fav){const x=items.find(i=>i.id===el.dataset.fav);if(x){x.favorite=!x.favorite;await put('interventions',x);await reload()}return}const a=el.dataset.action;if(!a)return;if(a==='save-google'){saveGoogleConfiguration();return}if(a==='choose-google'){await startGoogleImport(el);return}if(a==='disconnect-google'){disconnectGoogle();googleStatus('Google access disconnected. Library entries remain on this device.');return}if(a==='review-batch'){try{startImportReview()}catch(err){alert(err.message)}return}if(a==='commit-batch'){try{await commitImportReview()}catch(err){alert('Import failed: '+err.message)}return}if(a==='cancel-batch'){importBatch=[];setView('import');return}
 if(a==='toggle-sidebar'){sidebarCollapsed=!sidebarCollapsed;writeSetting('atlas-sidebar',sidebarCollapsed?'collapsed':'');render();$('.sidebar-toggle')?.focus();return}
 if(a==='cycle-theme'||a.startsWith('theme-')){theme=a==='cycle-theme'?{system:'light',light:'dark',dark:'system'}[theme]:a.slice(6);writeSetting('atlas-theme',theme);render();(a==='cycle-theme'?$('[data-action="cycle-theme"]'):$(`[data-action="${a}"]`))?.focus();return}
 if(a==='persist'){const granted=await navigator.storage?.persist?.().catch(()=>false);await refreshStorage();msg(granted?'Local data is now protected from automatic clearing':'This browser did not grant persistent storage. Keep exporting backups.');return}
 if(a==='add'){pendingProvenance=null;editId=null;query='';view='editor';render();window.scrollTo(0,0)}else if(a==='add-condition'){activeCondition='';view='condition-editor';render()}else if(a==='edit-condition'){view='condition-editor';render()}else if(a==='all-regions')setView('library');else if(a==='library'||a==='import')setView(a);else if(a==='cancel')setView('library',activeRegion);else if(a==='edit'){view='editor';render();window.scrollTo(0,0)}else if(a==='favorite-detail'){const x=items.find(i=>i.id===editId);x.favorite=!x.favorite;await put('interventions',x);await reload()}else if(a==='delete'){if(confirm('Permanently delete this intervention?')){await remove('interventions',editId);await reload();setView('library')}}else if(a==='delete-condition'){const c=conditions.find(x=>x.name===activeCondition&&x.region===activeRegion);if(c&&confirm('Delete this condition? Linked interventions will remain in the library.')){await remove('conditions',c.id);await reload();setView('library',activeRegion)}}else if(a==='export'){download(JSON.stringify({format:'pt-atlas',version:1,exportedAt:new Date().toISOString(),interventions:items,conditions},null,2),'pt-atlas-backup-'+today()+'.json')}else if(a==='review-import'){const text=$('#importText').value.trim();if(!text){alert('Paste your document text first.');return}const title=$('#importTitle').value.trim()||text.split('\n').find(Boolean)?.slice(0,160)||'Imported note';const source=$('#importSource').value.trim();pendingProvenance={sourceTitle:title,...textFileMetadata,sourceFile:textFileMetadata.fileName||'',sourceModifiedAt:textFileMetadata.fileModifiedAt||'',importedAt:new Date().toISOString(),reviewStatus:'unreviewed'};editId=null;view='editor';render();$('#name').value=title;document.querySelector('[name="notes"]').value=text;document.querySelector('[name="source"]').value=source;notice='Review the extracted text and choose a region and condition before saving'}});
window.addEventListener('popstate',()=>{applyRoute();render();window.scrollTo(0,0)});
window.addEventListener('online',updateNetworkStatus);window.addEventListener('offline',updateNetworkStatus);
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(theme==='system')applyTheme()});
(async()=>{try{db=await openDB();if(freshDatabase){for(const [region,name] of examples)await put('conditions',{id:uid(),region,name,overview:'',precautions:'',protocol:'',source:''})}applyRoute();await reload();refreshStorage();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;updateNetworkStatus()}).catch(()=>{offlineReady=false;msg('Offline cache unavailable. Your library is still saved locally.')})}catch(err){document.querySelector('#app').innerHTML='<div class="fatal">Unable to initialize offline storage. Check browser permissions or private browsing settings. '+escapeHTML(err.message)+'</div>'}})();

function startImportReview(){
 const text=$('#importText').value,title=$('#importTitle').value.trim(),source=sourceURL($('#importSource').value);
 importBatch=documentDrafts(text,title,$('#splitSections').checked).map(draft=>({...draft,region:activeRegion||regions[0],condition:''}));
 importMetadata={documentTitle:title||importBatch[0].name,source,importedAt:new Date().toISOString(),...textFileMetadata};
 view='import-review';query='';render();
}
function importReview(){return `<div class="page-head">${kicker('Document review')}<h1>Review imported entries</h1><p class="lede small">Source text is preserved. No clinical classification or dosage has been inferred. Imported entries are marked unreviewed. Nothing is saved until you confirm.</p><p class="row-meta">Document: ${escapeHTML(importMetadata.documentTitle)} · Source: ${escapeHTML(importMetadata.source||'Not supplied')}</p></div><form id="batchForm" class="form">${importBatch.map((draft,index)=>`<section class="panel draft" data-draft="${index}"><div class="draft-head"><span class="num">${String(index+1).padStart(2,'0')}</span><p class="row-meta">Source: ${escapeHTML(draft.metadata?.documentTitle||importMetadata.documentTitle)} · ${escapeHTML(draft.metadata?.source||importMetadata.source||'Local file or pasted text')}</p></div><div class="field"><label>Entry title</label><input name="title-${index}" value="${escapeHTML(draft.name)}" required maxlength="160"></div><div class="two"><div class="field"><label>Body region</label><select name="region-${index}">${regions.map(region=>`<option ${region===draft.region?'selected':''}>${escapeHTML(region)}</option>`).join('')}</select></div><div class="field"><label>Condition (optional)</label><input name="condition-${index}" value="${escapeHTML(draft.condition)}"></div></div><div class="field"><label>Imported source text</label><textarea name="notes-${index}">${escapeHTML(draft.notes)}</textarea></div><div class="field"><label>Duplicate handling</label><select name="decision-${index}"><option value="skip">Skip if title and region already exist</option><option value="new">Create a separate entry</option><option value="merge">Append source text to the matching entry (confirmation required)</option></select></div><p class="row-meta">${duplicateEntries(draft,items).length} existing title/region matches before edits. Matches are checked again when saving.</p><label class="toggle"><input type="checkbox" name="include-${index}" checked><span>Include this entry</span></label></section>`).join('')}<div class="actions sticky-actions">${btn('Confirm import','commit-batch','primary')}${btn('Cancel import','cancel-batch','ghost')}</div></form>`}
async function commitImportReview(){
 const form=$('#batchForm');if(!form.reportValidity())return;
 const data=new FormData(form),planned=[],working=[...items];let skipped=0,merged=0;
 for(let index=0;index<importBatch.length;index++){
  if(!data.has('include-'+index)){skipped++;continue}
  const draft={name:String(data.get('title-'+index)),region:String(data.get('region-'+index)),condition:String(data.get('condition-'+index)),notes:String(data.get('notes-'+index))};
  const matches=duplicateEntries(draft,working),decision=data.get('decision-'+index);
  if(matches.length&&decision==='skip'){skipped++;continue}
  if(matches.length>1&&decision==='merge')throw Error('Multiple entries match “'+draft.name+'”. Choose create separate or skip.');
  const metadata=importBatch[index].metadata||importMetadata;
  let record=importRecord(draft,{...metadata,id:uid()});
  if(matches.length&&decision==='merge'){
   const old=matches[0];record={...old,notes:[old.notes,'Imported from '+(metadata.source||metadata.documentTitle)+' on '+metadata.importedAt,draft.notes].filter(Boolean).join('\n\n'),updated:record.updated,reviewStatus:'unreviewed',importHistory:JSON.stringify([...readImportHistory(old.importHistory),{...metadata}])};merged++;
   const prior=planned.findIndex(entry=>entry.id===old.id);if(prior!==-1)planned.splice(prior,1);
   working.splice(working.findIndex(entry=>entry.id===old.id),1);
  }
  planned.push(record);working.push(record);
 }
 if(!planned.length){msg('No entries to import. '+skipped+' skipped.');return}
 if(!confirm('Save '+planned.length+' entries? '+merged+' merges append imported text; '+skipped+' skipped. Existing structured fields are preserved.'))return;
 const tx=db.transaction('interventions','readwrite');for(const record of planned)tx.objectStore('interventions').put(record);await transactionDone(tx);
 importBatch=[];textFileMetadata={};view='library';await reload();msg('Imported '+planned.length+' entries locally; '+skipped+' skipped.');
}

function readImportHistory(value){try{const history=JSON.parse(value||'[]');return Array.isArray(history)?history.filter(entry=>entry&&typeof entry==='object'&&!Array.isArray(entry)):[]}catch{return []}}

function readGoogleConfiguration(){try{return JSON.parse(localStorage.getItem('atlas-google-config')||'{}')||{}}catch{return {}}}
function googleImportPanel(){const config=readGoogleConfiguration();return `<div class="panel"><h2>${icon('library',20)} Connect Google Docs</h2><p class="muted">Choose up to 10 Google Docs, including documents inside folders. Only files you select are authorized. Internet is required to connect and read documents; reviewed imports work offline afterward. Google libraries load only when you click the connection button.</p><details><summary>Google connection setup</summary><p class="muted">Enter public browser configuration from your Google Cloud project. Never enter a client secret. See GOOGLE_SETUP.md in the repository for API, consent, and origin setup.</p><div class="field"><label for="googleClientId">Web OAuth client ID</label><input id="googleClientId" value="${escapeHTML(config.clientId||'')}" autocomplete="off"></div><div class="field"><label for="googleApiKey">Picker API key</label><input id="googleApiKey" value="${escapeHTML(config.apiKey||'')}" autocomplete="off"></div><div class="field"><label for="googleProjectNumber">Google Cloud project number</label><input id="googleProjectNumber" value="${escapeHTML(config.projectNumber||'')}" inputmode="numeric"></div>${btn('Save Google setup','save-google','ghost')}</details><label class="toggle"><input type="checkbox" id="googleSplit"><span>Split Google Doc headings into entries</span></label><div class="actions">${btn('Choose Google Docs','choose-google','primary')}${btn('Disconnect Google','disconnect-google','ghost')}</div><p id="googleStatus" class="muted" role="status" aria-live="polite">${config.clientId?'Configuration saved in this browser.':'Google setup is required before connecting.'}</p><p class="row-meta">Access tokens stay in memory and expire. Disconnect revokes the current token; to remove all previously granted access, use your Google Account connections settings. PT Atlas only reads selected documents and never modifies them in Drive.</p></div>`}
function googleStatus(message){const status=$('#googleStatus');if(status)status.textContent=message;}
function saveGoogleConfiguration(){try{const config=validateGoogleConfig({clientId:$('#googleClientId').value,apiKey:$('#googleApiKey').value,projectNumber:$('#googleProjectNumber').value});disconnectGoogle();localStorage.setItem('atlas-google-config',JSON.stringify(config));googleStatus('Google setup saved in this browser. Choose Google Docs to continue.');}catch(error){googleStatus(error.message)}}
async function startGoogleImport(button){
 const container=button.closest('.panel');
 try{
  if(!navigator.onLine)throw Error('Google import needs an internet connection. Local files and your saved library remain available offline.');
  const config=validateGoogleConfig(readGoogleConfiguration());
  button.disabled=true;
  if(!googleReady()){googleStatus('Loading Google connection…');await prepareGoogle();if(container.isConnected)googleStatus('Google connection ready. Click Choose Google Docs again to sign in and open the picker.');return;}
  const split=$('#googleSplit').checked;googleStatus('Choose documents in Google. Selected content will open for review.');
  const documents=await chooseGoogleDocuments(config,{split});
  if(!container.isConnected)return;
  if(!documents.length){googleStatus('Selection cancelled. Nothing was imported.');return;}
  const drafts=documents.flatMap(document=>documentDrafts(document.text,document.metadata.documentTitle,document.split).map(draft=>({...draft,region:activeRegion||regions[0],condition:'',metadata:document.metadata})));
  if(drafts.length>100)throw Error('This selection creates more than 100 entries. Choose fewer documents or turn off heading splitting.');
  importBatch=drafts;importMetadata={documentTitle:documents.length+' selected Google Docs',source:''};view='import-review';query='';render();
 }catch(error){if(container.isConnected)googleStatus('Google import failed: '+error.message);}
 finally{if(button.isConnected)button.disabled=false;}
}
